layers.shader:
#uicontrol bool channel0_visible checkbox(default=true);
#uicontrol vec3 channel0_color color(default ="#FF0000");
vec3 channel0 = vec3(0); 
#uicontrol invlerp channel0_lut(range=[0, 728], window=[0, 65535], channel=[0], );
#uicontrol bool channel1_visible checkbox(default=true);
#uicontrol vec3 channel1_color color(default ="#00FF00");
vec3 channel1 = vec3(0); 
#uicontrol invlerp channel1_lut(range=[0, 721], window=[0, 65535], channel=[1], );
#uicontrol bool channel2_visible checkbox(default=true);
#uicontrol vec3 channel2_color color(default ="#0000FF");
vec3 channel2 = vec3(0); 
#uicontrol invlerp channel2_lut(range=[0, 4095], window=[0, 65535], channel=[2], );
void main() { 
if (channel0_visible == true) channel0 = channel0_color * ((channel0_lut(getDataValue(0)) ));
if (channel1_visible == true) channel1 = channel1_color * ((channel1_lut(getDataValue(1)) ));
if (channel2_visible == true) channel2 = channel2_color * ((channel2_lut(getDataValue(2)) ));
vec3 rgb = (channel0 + channel1 + channel2);
float maxValue = max(max(max(rgb.x, rgb.y), rgb.z),0.01);
vec4 rgba = vec4(rgb, maxValue);
vec4 render = min(rgba,vec4(1));
emitRGBA(render);
}
